package dev.atqiya.ledgerly.imports.application;
import dev.atqiya.ledgerly.imports.domain.*; import dev.atqiya.ledgerly.imports.infrastructure.*; import dev.atqiya.ledgerly.ledger.domain.*; import dev.atqiya.ledgerly.ledger.infrastructure.LedgerTransactionRepository; import dev.atqiya.ledgerly.workspace.application.WorkspaceAccessService; import dev.atqiya.ledgerly.workspace.domain.*;
import java.io.*; import java.math.*; import java.nio.charset.StandardCharsets; import java.security.*; import java.time.*; import java.util.*; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import org.springframework.web.multipart.MultipartFile;
@Service public class StatementImportService{
 private static final Set<WorkspaceRole> EDITORS=Set.of(WorkspaceRole.OWNER,WorkspaceRole.ADMIN,WorkspaceRole.MEMBER);
 private final StatementImportRepository imports; private final StatementImportRowRepository rows; private final LedgerTransactionRepository transactions; private final WorkspaceAccessService access;
 public StatementImportService(StatementImportRepository i,StatementImportRowRepository r,LedgerTransactionRepository t,WorkspaceAccessService a){imports=i;rows=r;transactions=t;access=a;}
 @Transactional public ImportView preview(UUID userId,UUID workspaceId,MultipartFile file)throws IOException{
  var m=access.requireRole(userId,workspaceId,EDITORS); var batch=new StatementImport(UUID.randomUUID(),m.getWorkspace(),Optional.ofNullable(file.getOriginalFilename()).orElse("statement.csv"),m.getUser(),Instant.now());imports.save(batch);
  var parsed=new ArrayList<StatementImportRow>(); try(var reader=new BufferedReader(new InputStreamReader(file.getInputStream(),StandardCharsets.UTF_8))){String line;int n=0;while((line=reader.readLine())!=null){n++;if(n==1&&line.toLowerCase().contains("date"))continue;String[] p=line.split(",",3);LocalDate d=null;BigDecimal a=null;String desc=p.length>1?p[1].strip():null,error=null;TransactionType type=null;try{d=LocalDate.parse(p[0].strip());a=new BigDecimal(p[2].strip());type=a.signum()>=0?TransactionType.INCOME:TransactionType.EXPENSE;a=a.abs();if(a.signum()==0||desc.isBlank())throw new IllegalArgumentException();}catch(Exception e){error="Expected date,description,signed amount.";}String fp=error==null?hash(d+"|"+desc.toLowerCase()+"|"+a+"|"+type):null;boolean dup=fp!=null&&rows.existsByWorkspace_IdAndFingerprint(workspaceId,fp);parsed.add(new StatementImportRow(UUID.randomUUID(),batch,m.getWorkspace(),n,d,desc,a,type,fp,error,dup));}}
  rows.saveAll(parsed);batch.totals(parsed.size(),(int)parsed.stream().filter(StatementImportRow::importable).count(),(int)parsed.stream().filter(StatementImportRow::isDuplicate).count());return ImportView.from(batch,parsed);
 }
 @Transactional public ImportView confirm(UUID userId,UUID workspaceId,UUID id){var m=access.requireRole(userId,workspaceId,EDITORS);var batch=imports.findByIdAndWorkspace_Id(id,workspaceId).orElseThrow();var list=rows.findAllByStatementImport_IdOrderByRowNumber(id);for(var r:list)if(r.importable()){var t=new LedgerTransaction(UUID.randomUUID(),m.getWorkspace(),null,r.getType(),r.getAmount(),m.getWorkspace().getDefaultCurrency(),r.getOccurredOn(),r.getDescription(),"Imported from "+batch.getFileName(),m.getUser(),Instant.now());transactions.save(t);r.link(t);}batch.confirm(Instant.now());return ImportView.from(batch,list);}
 private String hash(String value){try{return java.util.HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(value.getBytes(StandardCharsets.UTF_8)));}catch(NoSuchAlgorithmException e){throw new IllegalStateException(e);}}
}
